"""Launch description that brings up move_group (and its dependencies) for the
simple 3-joint arm, without relying on a pre-built colcon package."""

import os
import yaml

from launch import LaunchDescription
from launch_ros.actions import Node

PKG_DIR = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))


def load_file(relative_path):
    with open(os.path.join(PKG_DIR, relative_path), "r") as f:
        return f.read()


def load_yaml(relative_path):
    with open(os.path.join(PKG_DIR, relative_path), "r") as f:
        return yaml.safe_load(f)


def generate_launch_description():
    robot_description = {"robot_description": load_file("urdf/arm.urdf")}
    robot_description_semantic = {
        "robot_description_semantic": load_file("config/arm.srdf")
    }
    kinematics = {"robot_description_kinematics": load_yaml("config/kinematics.yaml")}
    joint_limits = {
        "robot_description_planning": load_yaml("config/joint_limits.yaml")
    }

    ompl_config = load_yaml("config/ompl_planning.yaml")
    planning_pipelines = {
        "planning_pipelines": ["ompl"],
        "default_planning_pipeline": "ompl",
        "ompl": ompl_config,
    }

    trajectory_execution = {
        "moveit_manage_controllers": False,
    }

    planning_scene_monitor_parameters = {
        "publish_planning_scene": True,
        "publish_geometry_updates": True,
        "publish_state_updates": True,
        "publish_transforms_updates": True,
    }

    move_group_node = Node(
        package="moveit_ros_move_group",
        executable="move_group",
        output="screen",
        parameters=[
            robot_description,
            robot_description_semantic,
            kinematics,
            joint_limits,
            planning_pipelines,
            trajectory_execution,
            planning_scene_monitor_parameters,
            {"use_sim_time": False},
        ],
    )

    robot_state_publisher_node = Node(
        package="robot_state_publisher",
        executable="robot_state_publisher",
        output="screen",
        parameters=[robot_description, {"use_sim_time": False}],
    )

    joint_state_publisher_node = Node(
        package="joint_state_publisher",
        executable="joint_state_publisher",
        output="screen",
        parameters=[robot_description, {"use_sim_time": False}, {"rate": 30}],
    )

    return LaunchDescription(
        [
            robot_state_publisher_node,
            joint_state_publisher_node,
            move_group_node,
        ]
    )

